function calcEquation(equations: string[][], values: number[], queries: string[][]): number[] {
  // Взвешенный граф: ребро a -> b с весом k означает a / b = k
  const graph = new Map<string, [string, number][]>();
  const addEdge = (from: string, to: string, w: number): void => {
    if (!graph.has(from)) graph.set(from, []);
    graph.get(from)!.push([to, w]);
  };
  equations.forEach(([a, b], i) => {
    addEdge(a, b, values[i]); // a / b = k
    addEdge(b, a, 1 / values[i]); // b / a = 1 / k
  });

  // DFS: ищем путь от cur до target, перемножая веса рёбер по пути
  const dfs = (cur: string, target: string, product: number, visited: Set<string>): number => {
    if (cur === target) return product;
    visited.add(cur);
    for (const [next, w] of graph.get(cur)!) {
      if (visited.has(next)) continue;
      const res = dfs(next, target, product * w, visited);
      if (res !== -1) return res;
    }
    return -1; // из этой вершины цель недостижима
  };

  return queries.map(([c, d]) => {
    // Неизвестная переменная — ответа нет (даже для x / x)
    if (!graph.has(c) || !graph.has(d)) return -1;
    return dfs(c, d, 1, new Set<string>());
  });
}

// Время: O(Q · (V + E)) — для каждого запроса отдельный обход графа
// Память: O(V + E) — граф, visited и стек рекурсии
